  ARRAY['Unlimited domestic lounge access by swiping the Times Black ICICI card for primary and add-on cardholders', 'Unlimited international lounge access for primary and add-on cardholders via Priority Pass', '₹10,000 Times Black Visa Wallet for visa services via Atlys and OneVasco after joining-benefit activation', '₹10,000 Times Black Mobility Wallet unlocked after ₹5L spend for BLADE, Avis and Indian Travel House transfers', '1% fuel surcharge waiver on all fuel transactions · capped at ₹1,000 per statement cycle', 'Zero cancellation cover on eligible domestic flight, hotel and movie bookings · plus premium travel and accident insurance cover']::text[],
